def build_full_output():
    grid = [[9] * 18 for _ in range(7)]

    # Value 1: from positions (5,1) and (6,2), diagonal diff = r-c = 4
    for i in range(7):
        c = i - 4
        if 0 <= c < 18:
            grid[i][c] = 1

    # Value 5: from position (4,1), diagonal diff = r-c = 3
    for i in range(7):
        c = i - 3
        if 0 <= c < 18:
            grid[i][c] = 5

    # Value 5 again: from position (3,2), diagonal diff = r-c = 1
    for i in range(7):
        c = i - 1
        if 0 <= c < 18:
            grid[i][c] = 5

    # Value 4: from position (4,0), diagonal diff = r-c = 4
