def find_chains_and_extend():
    rows, cols = 7, 18

    lines = [
        ['9']*18 for _ in range(7)
    ]
    lines[3][2] = '5'
    lines[4][0] = '4'
    lines[4][1] = '5'
    lines[5][0] = '2'
    lines[5][1] = '1'
    lines[6][2] = '1'

    pixels = []
    for r in range(rows):
        for c in range(cols):
            val = int(lines[r][c])
            if val != 9:
                pixels.append((r, c, val))

    visited = set()
    used = set()
    chain_id = 0
    chains = {}

    def get_val(r, c):
        return int(lines[r][c])

    for pr, pc, pv in pixels:
        if (pr, pc) in used:
            continue

        stack = [(pr, pc)]
        chain_cells = []

        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in used:
                continue

            used.add((cr, cc))
            chain_cells.append((cr, cc, get_val(cr, cc)))

            for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    nval = get_val(nr, nc)
                    if nval == pv and (nr, nc) not in used:
                        stack.append((nr, nc))

        chains[chain_id] = sorted(chain_cells)
        chain_id += 1

    print("Chains found:", chains)

    grid_out = [[9] * cols for _ in range(rows)]

    # Extend each chain
    for cid, cells in chains.items():
        r0, c0, v = cells[0]
        diff = r0 - c0
        for r in range(rows):
            c = r - diff
            if 0 <= c < cols:
                grid_out[r][c] = v

    return grid_out, chains

grid_out, chains = find_chains_and_extend()
print("\nOutput grid:")
for r in range(7):
    row_str = ' '.join(str(x) for x in grid_out[r])
    print(f"{r}: [{row_str}]")

def solve_v6():
    rows, cols = 7, 18

    input_grid = [
        [9]*18 for _ in range(7)
    ]
    input_grid[3][2] = 5
    input_grid[4][0] = 4
    input_grid[4][1] = 5
    input_grid[5][0] = 2
    input_grid[5][1] = 1
    input_grid[6][2] = 1

    # Find multi-pixel chains
    used = set()
    chains = []  # list of (chain_cells, value, diagonal_type, diag_constant)

    def diag_id(r, c, typ='NWSE'):  # 'NWSE' = r-c const, 'NESW' = r+c const
        return ('NWSE', r-c) if typ == 'NWSE' else ('NESW', r+c)

    for r in range(rows):
        for c in range(cols):
            v = input_grid[r][c]
            if v == 9 or (r,c) in used:
                continue

            # BFS for diagonal adjacency
            queue = [(r, c)]
            used.add((r, c))
            chain = [(r, c)]

            while queue:
                cr, cc = queue.pop()
                for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        nv = input_grid[nr][nc]
                        if nv == v and (nr, nc) not in used:
                            used.add((nr, nc))
                            queue.append((nr, nc))
                            chain.append((nr, nc))

            if len(chain) >= 2:
                # Determine diagonal type
                diffs = set(c[0]-c[1] for c in chain)  # r-c values
                sums = set(c[0]+c[1] for c in chain)    # r+c values

                if len(diffs) == 1:
                    chains.append((sorted(chain), v, 'NWSE', list(diffs)[0]))
                elif len(sums) == 1:
                    chains.append((sorted(chain), v, 'NESW', list(sums)[0]))
                else:
                    # Mixed pattern? Skip for now
                    pass

    print("Multi-pixel chains:")
    for ch, v, dtype, dconst in chains:
        print(f"  {v}: {ch}, type={dtype}, constant={dconst}")

    # Build output
    result = [[9]*cols for _ in range(rows)]

    # Sort chains by reading order (top-left first)
    chains.sort(key=lambda x: x[0][0])

    for ch, v, dtype, dconst in chains:
        if dtype == 'NWSE':
            # All cells on diagonal where r - c = dconst
            for r in range(rows):
                c = r - dconst
                if 0 <= c < cols:
                    result[r][c] = v
        elif dtype == 'NESW':
            # All cells on anti-diagonal where r + c = dconst
            for r in range(rows):
                c = dconst - r
                if 0 <= c < cols:
                    result[r][c] = v

    return result

result = solve_v6()
print("\nOutput grid:")
for r in range(7):
    print(f"{r}: {' '.join(str(x) for x in result[r][:18])}")

def solve_v7():
    rows, cols = 7, 18

    input_grid = [
        [9]*18 for _ in range(7)
    ]
    input_grid[3][2] = 5
    input_grid[4][0] = 4
    input_grid[4][1] = 5
    input_grid[5][0] = 2
    input_grid[5][1] = 1
    input_grid[6][2] = 1

    # Find all diagonal chains
    used = set()
    chains = []

    for r in range(rows):
        for c in range(cols):
            v = input_grid[r][c]
            if v == 9 or (r,c) in used:
                continue

            queue = [(r, c)]
            used.add((r, c))
            chain_cells = [(r, c)]

            while queue:
                cr, cc = queue.pop()
                for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        nv = input_grid[nr][nc]
                        if nv == v and (nr, nc) not in used:
                            used.add((nr, nc))
                            queue.append((nr, nc))
                            chain_cells.append((nr, nc))

            sorted_chain = sorted(chain_cells)
            chains.append((sorted_chain, v))

    print("All chains:")
    for ch, v in chains:
        print(f"  {v}: {ch}")

    # Sort by first cell position (reading order)
    chains.sort(key=lambda x: x[0][0])

    # Build result with conflict resolution
    result = [[None]*cols for _ in range(rows)]

    for idx, ((cr, cc), v) in enumerate(zip([c[0] for c in chains], [chains[i][1] for i in range(len(chains))])):
        ch = [c[0] for c in chains][idx]
        val = [chains[i][1] for i in range(len(chains))][idx]

        if len(ch) < 2:
            continue

        diffs = set(r - c for r, c, _ in ch)
        sums = set(r + c for r, c, _ in ch)

        if len(diffs) == 1:
            diag_type = 'NWSE'
            dconst = list(diffs)[0]
        elif len(sums) == 1:
            diag_type = 'NESW'
            dconst = list(sums)[0]
        else:
            for r, c, _ in ch:
                result[r][c] = val
            continue

        for r in range(rows):
            if diag_type == 'NWSE':
                c = r - dconst
            else:
                c = dconst - r

            if 0 <= c < cols:
                if result[r][c] is None:
                    result[r][c] = val

    return result

