def extend_into_empty():
    rows, cols = 7, 18

    # Copy input grid
    grid = [row[:] for row in [
        [9]*18 for _ in range(7)
    ]]
    grid[3][2] = 5
    grid[4][0] = 4
    grid[4][1] = 5
    grid[5][0] = 2
    grid[5][1] = 1
    grid[6][2] = 1

    # Find all diagonal chains
    used = set()
    chains = []

    def neighbors(p):
        cr, cc, cv = p
        result = []
        for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                nv = grid[nr][nc]
                if nv == cv:
                    result.append((nr, nc))
        return result

    for pr, pc in [(r,c) for r in range(rows) for c in range(cols) if grid[r][c] != 9]:
        if (pr, pc) in used:
            continue

        queue = [(pr, pc)]
        used.add((pr, pc))
        chain = [(pr, pc)]

        while queue:
            curr = queue.pop(0)
            cr, cc = curr

            for nr, nc in neighbors((cr, cc, grid[cr][cc])):
                if (nr, nc) not in used:
                    used.add((nr, nc))
                    queue.append((nr, nc))
                    chain.append((nr, nc))

        sorted_chain = sorted(chain)
        chains.append(sorted_chain)

    print("Chains:")
    for ch in chains:
        print(f"  {ch}")

    result = [row[:] for row in grid]  # Start with input

    # Process chains in reading order
    chains_sorted = sorted(chains, key=lambda x: (x[0][0], x[0][1]))

    for ch in chains_sorted:
        if len(ch) < 2:
            continue

        val = ch[0][2]  # value from first cell
        diffs = set(r - c for r, c in ch)
        sums = set(r + c for r, c in ch)

        if len(diffs) == 1:
            dconst = list(diffs)[0]
            diag_cells = []
            for r in range(rows):
                c = r - dconst
                if 0 <= c < cols:
                    diag_cells.append((r, c))

            # For each cell on diagonal, fill if currently 9
            for r, c in diag_cells:
                if result[r][c] == 9:
                    result[r][c] = val

        elif len(sums) == 1:
            dconst = list(sums)[0]
            diag_cells = []
            for r in range(rows):
                c = dconst - r
                if 0 <= c < cols:
                    diag_cells.append((r, c))

            for r, c in diag_cells:
                if result[r][c] == 9:
                    result[r][c] = val

    print("\nResult grid (only filling empty cells):")
    for r in range(7):
        print(f"{r}: {' '.join(str(x) for x in result[r][:18])}")

    return result

